static const Line NL_0_0[] = {
  { "Abitante", "Ho sentito che qualcuno sta radunando i Sigilli delle Ore. Che il cielo vi assista!" }
};
static const Line NL_0_1[] = {
  { "Abitante", "Benvenuti! Scusate il disordine: con tutto questo tempo impazzito non si riesce pi\205 a tenere una casa." }
};
static const Line NL_1_0[] = {
  { "Abitante", "Una casa col camino acceso \201 il miglior rifugio quando le ore ballano." },
  { "Abitante", "Restate quanto volete, ma non toccate la credenza." }
};
static const Line NL_2_0[] = {
  { "Bottegaio", "Benvenuti nella mia bottega! Avvicinatevi al bancone per vedere la merce." }
};
static const Line NL_3_0[] = {
  { "Oste", "Benvenuti! Un letto caldo e una zuppa migliore di quella di mia suocera. Avvicinatevi al bancone!" }
};
static const Line NL_4_0[] = {
  { "Sacerdote", "Questo \201 un luogo di pace. Avvicinatevi all\220altare e la luce vi ristorer\200." },
  { "Sacerdote", "Anche quando il tempo trema, la fede resta ferma." }
};
static const Line NL_5_0[] = {
  { "Rettore Cid", "Avete i Quattro Sigilli delle Ore... La barriera del Sacro Monte ceder\200." },
  { "Rettore Cid", "Eterna vi aspetta al Santuario. Andate, e che il tempo sia dalla vostra parte." }
};
static const Line NL_5_1[] = {
  { "Rettore Cid", "I Sigilli delle Ore sono custoditi nei paesi della provincia: Vedano, Castiglione, Jerago e Samarate." },
  { "Rettore Cid", "Senza tutti e quattro, nessuno pu\204 salire al Santuario del Sacro Monte." }
};
static const Line NL_5_2[] = {
  { "Rettore Cid", "..." }
};
static const Line NL_6_0[] = {
  { "Bibliotecaria", "Silenzio in biblioteca! ...Ah, siete voi. I tomi sui Sigilli delle Ore sono spariti tutti, guarda caso, la notte in cui \201 arrivata Eterna." },
  { "Bibliotecaria", "Se trovate libri in giro per la provincia, riportateli. Le multe per il ritardo si accumulano anche in tempo di crisi." }
};
static const Line NL_7_0[] = {
  { "Allievo", "Dicono che a Vedano Olona la vecchia Chiesa del Lazzaretto si sia... svegliata. Di notte suona la campana da sola. Brrr." }
};
static const Line NL_8_0[] = {
  { "Allieva", "Ste e Riki, vero? In bocca al lupo per l\220esame. Io l\220anno scorso sono svenuta davanti a un Lumacone." }
};
static const Line NL_9_0[] = {
  { "Cittadino", "Una volta dal Sacro Monte si vedeva tutta la provincia. Ora c\220\201 solo quella nube viola..." }
};
static const Line NL_10_0[] = {
  { "Cittadina", "Mio cugino abita a Samarate. Dice che dalle vecchie officine escono rumori di metallo... vivi." }
};
static const Line NL_11_0[] = {
  { "Giardiniere", "Benvenuti ai Giardini Estensi! Persino con una strega in giro, i fiori vanno annaffiati." }
};
static const Line NL_12_0[] = {
  { "Bimba", "La mamma dice che se faccio i capricci arriva la Strega del Tempo e mi fa diventare vecchia!" }
};
static const Line NL_13_0[] = {
  { "Mercante", "Frutta di stagione, stoffe di Gallarate, castagne del Campo dei Fiori!" },
  { "Mercante", "Col tempo impazzito vendo pesche a novembre. Non lamentiamoci di tutto, va\220." }
};
static const Line NL_14_0[] = {
  { "Bambino", "La fontana esprime i desideri! Io ho chiesto un drago. Il pap\200 dice di chiedere pioggia, che \201 pi\205 utile." },
  { "Bambino", "Se sali al castello saluta i fantasmi! Sono simpatici, ma stonano quando cantano." }
};
static const Line NL_15_0[] = {
  { "Nonna del parco", "Mio marito costruiva le ali degli aerei, qui alle officine. Diceva: \216Samarate ha sempre guardato in su\217." },
  { "Nonna del parco", "Anche voi guardate in su, giovani. Ma prima, una caramella? Ne ho di menta e di drago." }
};
static const Line NL_16_0[] = {
  { "Guardia", "Avete sistemato il Lazzaretto di Vedano? Allora provate a Castiglione Olona: la Collegiata \201 infestata, e c\220\201 chi dice di averci visto entrare un ladro." }
};
static const Line NL_16_1[] = {
  { "Guardia", "La strada per Vedano Olona parte a sud-est. State sulla via: nei campi gironzolano brutte bestie." }
};
static const Line NL_17_0[] = {
  { "Vecchio Sagrestano", "La campana del Lazzaretto ha smesso di suonare da sola. Quarant\220anni che tengo le chiavi di quella chiesa, e non avevo mai sentito un silenzio cos\203 bello." },
  { "Vecchio Sagrestano", "A Castiglione, dicono, un ladro e una ragazza con l\220arco si sono chiusi nella Collegiata. Gente strana, di questi tempi." }
};
static const Line NL_17_1[] = {
  { "Vecchio Sagrestano", "Voi due siete dell\220Accademia? Allora ascoltate." },
  { "Vecchio Sagrestano", "La Chiesa del Lazzaretto, gi\205 a est del paese, fu costruita per i malati della peste, secoli fa. Da quando \201 arrivata la nube viola, di notte la campana suona da sola." },
  { "Vecchio Sagrestano", "Dentro, la vecchia statua del guardiano si \201 mossa. Tiene tra le mani un sigillo che brilla come l\220alba." },
  { "Vecchio Sagrestano", "Uscite dalla piazza di San Rocco verso est e seguite la strada tra i campi. Ho lasciato il chiavistello aperto: il resto \201 affar vostro." }
};
static const Line NL_18_0[] = {
  { "Signora con la spesa", "L\220alimentari qui in piazza San Rocco ha il pane pi\205 buono della valle. Da quando c\220\201 la nube viola, per\204, lievita al contrario." }
};
static const Line NL_19_0[] = {
  { "Ragazzo in bici", "Via Monetti di sera \201 tranquillissima. Se trovi un monopattino abbandonato, prendilo: io il mio l\220ho perso inseguendo un Lumacone." }
};
static const Line NL_20_0[] = {
  { "Contadino", "Tra i campi verso il Lazzaretto si sente una campana anche a mezzanotte. Io giro al largo, con la zappa in mano." }
};
static const Line NL_21_0[] = {
  { "Signore di Via Adua", "Da Via Adua si sale verso Varese. C\220era una Vespa parcheggiata qui da giorni: chi la trova, se la tenga... ma la tratti bene." }
};
static const Line NL_22_0[] = {
  { "Cittadino", "Di notte dal Lazzaretto si sentono passi di pietra. E la campana... chi la suona, se la chiesa \201 chiusa?" }
};
static const Line NL_23_0[] = {
  { "Anziano", "Ai miei tempi l\220Olona era piena di pesci. Ora \201 piena di serpi grosse come tubi." }
};
static const Line NL_24_0[] = {
  { "Custode del Palazzo", "Questo \201 il borgo del Cardinale Branda. Persino la sua ombra, dicono, non ha mai lasciato la Collegiata..." }
};
static const Line NL_25_0[] = {
  { "Pasq", "Mmh. Voi cercate il Sigillo del Meriggio." },
  { "Pasq", "\207 nella Collegiata, ma qualcosa di antico lo tiene stretto. E non siete i primi: stanotte un ladro \201 entrato per rubarlo." },
  { "Pasq", "Dietro di lui \201 corsa dentro una ragazza con l\220arco, urlando il suo nome. Da allora, solo rumori." },
  { "Pasq", "Vi apro la strada. I miei pugni pregano a modo loro." }
};
static const Line NL_26_0[] = {
  { "Pittore", "Studio gli affreschi di Masolino. Ultimamente... le figure dipinte mi seguono con lo sguardo." }
};
static const Line NL_27_0[] = {
  { "Dama", "Il borgo \201 un gioiello del Quattrocento. Peccato per gli spettri. Rovinano il turismo." }
};
static const Line NL_28_0[] = {
  { "Castellano", "Il castello \201 di nuovo silenzioso. Vero e Mirko vi hanno seguito? Lei canta ai fantasmi del mastio da quando era bambina, lui la segue da quando l\220ha sentita." }
};
static const Line NL_28_1[] = {
  { "Castellano", "Nel Castello di Jerago si \201 insediato un cavaliere che non appartiene a questo tempo. Vero, la custode, \201 rimasta dentro!" },
  { "Castellano", "E il suo Mirko, quell\220omone con l\220ascia, \201 entrato a riprenderla. Da allora si sentono canti e colpi." }
};
static const Line NL_29_0[] = {
  { "Contadina", "Da Jerago, scendendo a sud-ovest, si arriva a Samarate. Occhio alle vespe: sono grosse come mucche." }
};
static const Line NL_30_0[] = {
  { "Meccanico", "Qui una volta si costruivano macchine volanti, sai? Adesso le officine si sono costruite... qualcos\220altro." }
};
static const Line NL_31_0[] = {
  { "Sofy", "Ste?! ...E Riki, ovviamente. Lo sapevo che prima o poi sareste arrivati." },
  { "Sofy", "La Collegiata mi ha mandata qui a proteggere gli operai. Nelle officine dorme un drago di lamiere e turbine, col Sigillo della Notte nel petto." },
  { "Sofy", "Tengo una barriera attorno alla pista da una settimana. Da sola non reggo ancora a lungo... ma in squadra, forse." }
};
static const Line NL_32_0[] = {
  { "Vecchio Pilota", "Ho volato su mezzo mondo, ma un drago d\220acciaio non l\220avevo mai visto. Quasi quasi \201 bello." }
};
