static const Line ES_0_D0[] = {
  { "", "Accademia del Sacro Monte - aula magna, ore 8:00." },
  { "Rettore Cid", "Ste. Riki. Avanti, niente cerimonie." },
  { "Ste", "Rettore. Ci ha convocati per l\220esame finale?" },
  { "Rettore Cid", "L\220esame \201 annullato. O meglio: \201 diventato reale." },
  { "Rettore Cid", "Questa notte una strega si \201 insediata nel Santuario del Sacro Monte. Si fa chiamare Eterna." },
  { "Riki", "...E vuole?" },
  { "Rettore Cid", "Comprimere il tempo. Tutte le epoche, schiacciate in un solo istante: il suo. Varese sarebbe solo l\220inizio." },
  { "Rettore Cid", "Il Santuario \201 protetto da una barriera che cede solo ai Quattro Sigilli delle Ore: Alba, Meriggio, Vespro e Notte." },
  { "Rettore Cid", "Sono custoditi a Vedano Olona, Castiglione Olona, Jerago e Samarate. Ma i custodi... sono stati corrotti dal potere di Eterna." },
  { "Ste", "Quindi: cinque paesi, quattro mostri, una strega. Prima di pranzo \201 impossibile." },
  { "Riki", "Allora salteremo il pranzo." },
  { "Rettore Cid", "Da oggi siete operativi. Trovate alleati lungo la strada: da soli non arrivereste al Vespro." },
  { "", "Missione: raggiungete Vedano Olona, a sud-est di Varese." }
};
