static const Line ES_1_D0[] = {
  { "", "La porta della Chiesa del Lazzaretto cigola. Dentro fa freddo; le candele si accendono da sole, una dopo l\220altra." },
  { "Riki", "Quella statua in fondo... si \201 appena girata." },
  { "???", "CHI... DISTURBA... IL RIPOSO... DEI MIEI MALATI..." },
  { "Ste", "Il guardiano del lazzaretto. Eterna lo ha svegliato dopo quattro secoli." },
  { "Riki", "Parla pure la pietra." },
  { "Ste", "Solo noi due, come ai vecchi tempi. Io lo rallento, tu lo tagli." }
};
static const Line ES_1_D2[] = {
  { "", "Il Guardiano si ferma, si inginocchia e torna statua. Tra le sue mani di pietra brilla il SIGILLO DELL\220ALBA." },
  { "Riki", "Uno su quattro. E non abbiamo nemmeno saltato il pranzo." },
  { "Ste", "Il prossimo \201 a Castiglione Olona. L\203 da soli non basteremo." },
  { "", "Hai ottenuto il Sigillo dell\220Alba (1/4)! Prossima meta: Castiglione Olona." }
};
