static const Line ED_2_D0[] = {
  { "", "La Collegiata \201 tornata tiepida. Gli affreschi, giurereste, sorridono." }
};
static const Step ED_2[] = {
  { 0, 0, 1, ED_2_D0 }
};
static const Line ES_3_D0[] = {
  { "", "Il portone del Castello di Jerago \201 spalancato. Dal mastio scende una musica: qualcuno canta per tenere a bada qualcosa." },
  { "Vero", "Ospiti! Perfetto tempismo: la mia voce sta finendo." },
  { "Mirko", "E la mia ascia sta perdendo la pazienza. Voi siete quelli dell\220Accademia? Bene: pi\205 siamo, pi\205 botte." },
  { "Cavaliere Senza Tempo", "...ho servito questo castello per ottocento anni. Il Vespro \201 MIO." },
  { "Vero", "\207 un cavaliere del Trecento, poverino. Eterna gli ha promesso di riavere la sua epoca." },
  { "Riki", "Un guerriero di ottocento anni. Finalmente un avversario con esperienza." }
};
static const Line ES_3_D2[] = {
  { "", "Il cavaliere si inginocchia, e per un istante l\220armatura \201 di nuovo lucida, giovane. Poi, polvere. Resta il SIGILLO DEL VESPRO." },
  { "Vero", "Riposa, messere. ...Bene! Veniamo con voi. Il castello sa badare a s\202, e voi avete una strega da spodestare." },
  { "Ste", "Sai combattere?" },
  { "Vero", "So chiamare chi combatte per me. \207 molto pi\205 elegante. E poi c\220\201 lui." },
  { "Mirko", "Io sono quello che combatte in modo MENO elegante. Niente battute sulla differenza d\220altezza tra me e lei: le ha gi\200 fatte tutte." },
  { "", "Vero e Mirko si sono uniti alla squadra! Hai ottenuto il Sigillo del Vespro (3/4). Ultima meta: Samarate." }
};
