static const Line ED_3_D0[] = {
  { "", "Il castello \201 quieto. Sul mastio, una bandiera nuova saluta il tramonto." }
};
static const Step ED_3[] = {
  { 0, 0, 1, ED_3_D0 }
};
static const Line ES_4_D0[] = {
  { "", "Le officine di Samarate ruggiscono. Sulla pista, dentro un anello di luce dorata, dorme un drago di lamiere." },
  { "Sofy", "La barriera sta cedendo... Ste, Riki: quando si rompe, colpite insieme." },
  { "Riki", "Arrotolato come un gatto. Un gatto di quaranta tonnellate." },
  { "Mirko", "Io dico di svegliarlo con l\220ascia." },
  { "Sofy", "Il piano prevedeva SILENZIO-" },
  { "Drago d\220Acciaio", "...SISTEMI DI COMBATTIMENTO... RIATTIVATI..." },
  { "Mirko", "Visto? Si \201 svegliato da solo. Risparmiata un\220ascia." }
};
static const Line ES_4_D2[] = {
  { "", "Il drago si affloscia con un lungo sibilo di vapore. Dal suo petto rotola il SIGILLO DELLA NOTTE." },
  { "Mirko", "Vero canter\200 per un mese quando le racconto che ho cavalcato un drago." },
  { "Vero", "Non l\220hai cavalcato." },
  { "Mirko", "L\220ho cavalcato EMOTIVAMENTE." },
  { "Sofy", "Ste... te l\220avevo detto: ovunque tu vada, ci ritroviamo sempre." },
  { "Ste", "...Riki. Smettila di sorridere." },
  { "Riki", "Non sto sorridendo. Sto ARCHIVIANDO." },
  { "Sofy", "Vengo con voi al Sacro Monte. La mia luce vi servir\200 contro Eterna. E poi qualcuno deve tenere d\220occhio Ste." },
  { "", "Sofy si \201 unita alla squadra! Hai ottenuto il Sigillo della Notte (4/4)." },
  { "", "La barriera del Sacro Monte ora pu\204 essere infranta. Tornate a nord-ovest di Varese!" }
};
