static const Line ED_4_D0[] = {
  { "", "Le officine tacciono. Sul piazzale, il vento muove solo foglie e bulloni." }
};
static const Step ED_4[] = {
  { 0, 0, 1, ED_4_D0 }
};
static const Line ES_5_D0[] = {
  { "", "Il Santuario del Sacro Monte. Le quattordici cappelle brillano come una collana di stelle sotto la nube viola." },
  { "Eterna", "Benvenuti, frammenti di presente." },
  { "Eterna", "Ho visto mille epoche di questa provincia: i romani sul lago, il Cardinale nel suo borgo, le macchine volanti di Samarate..." },
  { "Eterna", "Tutte MERAVIGLIOSE. Tutte PERDUTE. Io le salver\204: un solo istante, eterno, dove nulla muore." },
  { "Ste", "Un istante dove nulla vive, vuoi dire." },
  { "Riki", "Il tempo scorre. \207 questo che lo rende prezioso." },
  { "Eterna", "...Allora scorrete via." }
};
static const Line ES_5_D2[] = {
  { "", "La clessidra di Eterna si incrina. La nube viola si squarcia, e per la prima volta dopo settimane... l\220alba tocca il lago." },
  { "Eterna", "...cos\203 tanto futuro... e nessuna paura...?" },
  { "Ste", "Tanta. Ma la condividiamo. \207 il trucco." },
  { "", "La Strega del Tempo si dissolve in granelli di sabbia dorata, che il vento porta via verso le Prealpi." }
};
