static const Line QL_0_offer[] = {
  { "Giardiniere", "Benvenuti ai Giardini Estensi! O meglio... a quel che ne resta." },
  { "Giardiniere", "I Lumaconi del Lago salgono di notte e si mangiano le aiuole. Trent\220anni di lavoro, ridotti a insalata!" },
  { "Giardiniere", "Se me ne togliete di mezzo TRE, vi ricompenso con quel che ho." }
};
static const Line QL_0_accepted[] = {
  { "Giardiniere", "Grazie! Li trovate nei prati attorno alla citt\200. Colpite forte: sotto il muco sono permalosi." }
};
static const Line QL_0_progress[] = {
  { "Giardiniere", "Come va la caccia? Le mie ortensie contano su di voi." }
};
static const Line QL_0_complete[] = {
  { "Giardiniere", "Tre lumaconi in meno! Sento gi\200 le aiuole respirare." },
  { "Giardiniere", "Tenete: pozioni di calendula fatte in casa. E questa mancia per il disturbo." }
};
static const Line QL_0_after[] = {
  { "Giardiniere", "I fiori rinascono. Quando tutto questo sar\200 finito, vi pianto una siepe a forma di gruppo." }
};
static const Line QL_1_offer[] = {
  { "Bimba", "Snif... il mio gatto Ambrogio \201 scappato sul campanile e non scende pi\205!" },
  { "Bimba", "Ha paura dei corvi cattivi. Voi siete grandi e grossi... li mandate via voi? Due bastano, gli altri sono suoi amici." }
};
static const Line QL_1_accepted[] = {
  { "Bimba", "Evviva! I corvi cattivi stanno nei prati fuori citt\200. Ambrogio vi guarda dal campanile!" }
};
static const Line QL_1_progress[] = {
  { "Bimba", "Ambrogio \201 ancora lass\205. Miagola in do minore, dice il campanaro." }
};
static const Line QL_1_complete[] = {
  { "Bimba", "AMBROGIO! Sei sceso! ...Vi ha visto combattere e dice che siete i suoi eroi." },
  { "Bimba", "La mamma mi ha dato questa campanella per voi. E anche i miei risparmi. Tutti e cinquanta!" }
};
static const Line QL_1_after[] = {
  { "Bimba", "Ambrogio adesso dorme sulla panchina dei giardini. Come un re." }
};
static const Line QL_2_offer[] = {
  { "Custode del parco", "Ammiratelo: il Colosso del parco di Vedano. C\220\201 chi lo chiama Gundam, chi \216il robottone\217. Io lo chiamo capolavoro." },
  { "Custode del parco", "Ma guardate la corazza: tutta scrostata! Serve la Vernice Speciale, quella dei vecchi modellisti." },
  { "Custode del parco", "Ne restano tre barattoli, chiusi in forzieri sparsi tra il parco e le campagne. Portatemeli e non ve ne pentirete." }
};
static const Line QL_2_accepted[] = {
  { "Custode del parco", "Un barattolo \201 qui nel parco, gli altri nei boschi a est e a sud. Occhio ai lupi!" }
};
static const Line QL_2_progress[] = {
  { "Custode del parco", "Trovata la vernice? Il Colosso non si ridipinge da solo. Purtroppo." }
};
static const Line QL_2_complete[] = {
  { "Custode del parco", "TRE barattoli! Bianco, blu e rosso: i suoi colori. Domani il Colosso torna a splendere." },
  { "Custode del parco", "Questa \201 per voi. E quando passate di qui... salutatelo. Porta fortuna, sapete?" }
};
static const Line QL_2_after[] = {
  { "Custode del parco", "Guardatelo come brilla! Dicono che di notte gli occhi si accendano. Io dico che veglia su Vedano." }
};
static const Line QL_3_offer[] = {
  { "Anziano", "Ai miei tempi l\220Olona era piena di pesci. Ora \201 piena di lupi che ululano al gelo." },
  { "Anziano", "I pescatori non scendono pi\205 alla riva. Quattro lupi in meno e il paese tornerebbe a mangiare pesce fresco." }
};
static const Line QL_3_accepted[] = {
  { "Anziano", "Cercateli lungo il fiume e nei boschi. E copritevi: il loro ululato gela le ossa." }
};
static const Line QL_3_progress[] = {
  { "Anziano", "Li sento ancora ululare, la notte. Contateli bene: quattro." }
};
static const Line QL_3_complete[] = {
  { "Anziano", "Stanotte, silenzio. Solo il fiume. Non sentivo questa pace da vent\220anni." },
  { "Anziano", "Tenete, da parte mia e dei pescatori. E domani, frittura per tutti!" }
};
static const Line QL_3_after[] = {
  { "Anziano", "Il primo luccio l\220abbiamo chiamato come voi. Spero non vi offenda: \201 un bel luccio." }
};
static const Line QL_4_offer[] = {
  { "Pittore", "Studio gli affreschi di Masolino da dieci anni. Ultimamente... le figure mi seguono con lo sguardo." },
  { "Pittore", "Sono gli spettri del borgo: si infilano nei dipinti e li abitano! Come posso restaurare un santo che sbadiglia?" },
  { "Pittore", "Dissolvetene quattro e i pennelli torneranno a danzare." }
};
static const Line QL_4_accepted[] = {
  { "Pittore", "Girano nel borgo vecchio e lungo il fiume, al crepuscolo. La luce sacra li spaventa, se l\220avete." }
};
static const Line QL_4_progress[] = {
  { "Pittore", "Stamattina la Madonna della cappella mi ha fatto l\220occhiolino. FATE PRESTO." }
};
static const Line QL_4_complete[] = {
  { "Pittore", "Gli affreschi sono tornati immobili! Beh, quasi: il committente nel pannello grande sorride. Ma quello sorrideva gi\200." },
  { "Pittore", "Ecco il compenso. E questi eteri: li usavo per sciogliere i pigmenti, a voi serviranno di pi\205." }
};
static const Line QL_4_after[] = {
  { "Pittore", "Ho aggiunto otto figurine in fondo all\220affresco nuovo. Una ha la coda di cavallo. Non ditelo al committente." }
};
static const Line QL_5_offer[] = {
  { "Dama", "Il borgo \201 un gioiello del Quattrocento, ma manca una gemma: la reliquia del Cardinale, sparita dalla Collegiata." },
  { "Dama", "Le malelingue accusano gli spettri. Io dico che \201 in uno di quei forzieri lass\205, vicino al colle della Collegiata." },
  { "Dama", "Riportatemela e la mia famiglia sapr\200 essere generosa." }
};
static const Line QL_5_accepted[] = {
  { "Dama", "Cercate sul colle, oltre il ponte. E maneggiatela con guanti di velluto, mi raccomando." }
};
static const Line QL_5_progress[] = {
  { "Dama", "La reliquia \201 ancora l\200 fuori. Il Cardinale, dovunque sia, tamburella le dita." }
};
static const Line QL_5_complete[] = {
  { "Dama", "La reliquia! Intatta! Il borgo vi deve un pezzo della sua anima." },
  { "Dama", "Questa Coda di Fenice appartiene alla mia famiglia da tre generazioni. Ora appartiene a voi." }
};
static const Line QL_5_after[] = {
  { "Dama", "La reliquia \201 tornata nella teca. I turisti fotografano, gli spettri si tengono a distanza. Perfetto." }
};
static const Line QL_6_offer[] = {
  { "Contadina", "Guardate i miei campi: sembrano arati da un esercito. Sono i cinghiali corazzati delle colline!" },
  { "Contadina", "Quattro di quelli in meno e il raccolto si salva. Ho messo da parte una ricompensa: il granoturco non si difende da solo." }
};
static const Line QL_6_accepted[] = {
  { "Contadina", "Battete le colline attorno al paese. E mirate al muso: la corazza, davanti, ha uno spiraglio." }
};
static const Line QL_6_progress[] = {
  { "Contadina", "Ne ho visto un altro stanotte. Grosso come il trattore. IL TRATTORE." }
};
static const Line QL_6_complete[] = {
  { "Contadina", "Il raccolto \201 salvo! Quest\220inverno si mangia polenta, e la dobbiamo a voi." },
  { "Contadina", "Ecco quanto promesso. La granpozione \201 ricetta di mia nonna: mais, miele e un segreto." }
};
static const Line QL_6_after[] = {
  { "Contadina", "I campi sono quieti. Ho persino rimesso lo spaventapasseri. Pi\205 che altro per compagnia." }
};
static const Line QL_7_offer[] = {
  { "Meccanico", "Qui una volta si costruivano macchine volanti. Adesso le macchine si costruiscono da sole - e vengono a rubarmi i bulloni!" },
  { "Meccanico", "Gli automi della cava mi hanno svuotato il magazzino. Smontatene tre e vi pago in oro e in miracoli di officina." }
};
static const Line QL_7_accepted[] = {
  { "Meccanico", "Girano nella brughiera. Se sentite un ticchettio idraulico... \201 tardi. Colpite i giunti!" }
};
static const Line QL_7_progress[] = {
  { "Meccanico", "Ne mancano ancora. Stanotte uno ha provato a smontare la mia bicicletta. LA BICICLETTA." }
};
static const Line QL_7_complete[] = {
  { "Meccanico", "Tre automi in pensione anticipata! Coi loro pezzi ci faccio un tostapane. Un tostapane ENORME." },
  { "Meccanico", "Ecco l\220oro. E questo elisir: lo teneva il mio maestro per le emergenze. Voi puntate a una strega: direi che conta." }
};
static const Line QL_7_after[] = {
  { "Meccanico", "Il magazzino \201 di nuovo pieno. Il tostapane gigante funziona. Colazione per tutto il paese!" }
};
